//! Links the pre-compiled Windows resources (mascot icons, version information) into
//! `sondpi.exe`. The resources are generated by `tools/ikon-uret.ps1` and committed, so a
//! normal build needs neither Edge nor the resource compiler. Library and test builds do not
//! get them; code that loads an icon from the resources must cope with that.

fn main() {
    println!("cargo:rerun-if-changed=assets/sondpi.res");
    println!("cargo:rerun-if-changed=build.rs");
    let dir = std::env::var("CARGO_MANIFEST_DIR").unwrap_or_default();
    let res = std::path::Path::new(&dir).join("assets").join("sondpi.res");
    let msvc = std::env::var("CARGO_CFG_TARGET_ENV").map(|v| v == "msvc").unwrap_or(false);
    if msvc && res.is_file() {
        println!("cargo:rustc-link-arg-bins={}", res.display());
    }
}
